import random

from deepagents import create_deep_agent
from langchain_core.messages import AIMessage
from langchain_core.tools import tool

from guion import ModeloGuion


@tool
def roll_dice(sides: int = 6) -> int:
    """Roll a die with the given number of sides and return the result."""
    return random.randint(1, sides)


model = ModeloGuion(guion=[
    AIMessage("", tool_calls=[{"name": "roll_dice", "args": {"sides": 20}, "id": "call_1"}]),
    AIMessage("Listo: tiraste el d20."),
])

agent = create_deep_agent(
    model=model,
    tools=[roll_dice],
)

result = agent.invoke(
    {"messages": [{"role": "user", "content": "Roll a 20-sided die for me."}]}
)

print("Tools que vio el modelo:", model.tools_vistas)
for message in result["messages"]:
    for call in getattr(message, "tool_calls", None) or []:
        print(f"Model asked for: {call['name']}({call['args']})")
    if message.type == "tool":
        print(f"Tool returned:   {message.content}  (tool_call_id={message.tool_call_id})")
print(f"Final answer:    {result['messages'][-1].text}")
print("Mensajes:", [m.type for m in result["messages"]])

from pathlib import Path

from langchain_community.utilities import SQLDatabase
from langchain_core.tools import tool

DB_PATH = Path(__file__).parent / "chinook.db"   # el chinook.db de python/m1
db = SQLDatabase.from_uri(f"sqlite:///{DB_PATH}")


@tool
def read_sql(query: str) -> str:
    """Run a read-only SELECT query against the Chinook music store database."""
    try:
        return str(db.run(query))
    except Exception as e:
        return f"Error: {e}"


print(read_sql.name, "|", read_sql.description)
print(read_sql.args)
print(read_sql.invoke({"query": "SELECT g.Name, COUNT(*) AS n FROM Track t JOIN Genre g ON t.GenreId = g.GenreId GROUP BY g.Name ORDER BY n DESC LIMIT 5"}))
print(read_sql.invoke({"query": "SELECT * FROM Generos"}))

